import{_ as o,o as t,c as s,ah as a}from"./chunks/framework.D4KxWb5R.js";const h=JSON.parse('{"title":"The desk","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/desk.md","filePath":"src/en/guide/desk.md"}'),n={name:"en/guide/desk.md"};function i(r,e,c,u,d,l){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="the-desk" tabindex="-1">The desk <a class="header-anchor" href="#the-desk" aria-label="Permalink to &quot;The desk&quot;">​</a></h1><p>The intranet is open to every active account. The left menu groups, under <strong>Intranet</strong>, your desk, communications and resources; under <strong>Administration</strong>, the functions of your position (absent if your position has none). <strong>View site</strong> opens the public site.</p><p>Everything you see is filtered by your <a href="./introduction.html#key-notions">scope</a>.</p><h2 id="my-desk" tabindex="-1">My desk <a class="header-anchor" href="#my-desk" aria-label="Permalink to &quot;My desk&quot;">​</a></h2><p>The intranet home page shows:</p><ul><li><strong>My scope</strong>: your products, zones and offices (&quot;All products and all zones&quot; for management);</li><li><strong>Latest communications</strong> and <strong>Recent resources</strong>;</li><li><strong>Product spaces</strong>: a way into each product of your scope;</li><li>alert banners depending on your position: new contact messages to handle, desynchronized products.</li></ul><p>If no position is assigned to you yet, the desk says so: ask the general administrator to complete your account.</p><h2 id="communications" tabindex="-1">Communications <a class="header-anchor" href="#communications" aria-label="Permalink to &quot;Communications&quot;">​</a></h2><p><strong>Communications</strong> lists the announcements that concern you: those addressed to all of M&#39;City, and those targeted at your position, your department, a product, zone or office of your scope, or at you by name. Each communication shows its author, date and target.</p><p>A communication is written in a single language, chosen by its author.</p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><p><strong>Resources</strong> gathers shared documents, procedures, notes, contacts and links. Filter by type; open a link or download a document.</p><ul><li>A <strong>general</strong> resource is visible to every account.</li><li>A resource tied to a product is visible only if your scope covers that product; it also appears in the product&#39;s space.</li></ul><h2 id="product-spaces" tabindex="-1">Product spaces <a class="header-anchor" href="#product-spaces" aria-label="Permalink to &quot;Product spaces&quot;">​</a></h2><p>Each active product of your scope has its space. It shows:</p><ul><li>the zones where the product operates;</li><li>the responsible teams and their members;</li><li>the product&#39;s own communications and resources;</li><li><strong>View the public page</strong>: its landing page on the site;</li><li><strong>Open the back-office</strong>: its back-office, without entering your credentials again.</li></ul><p>The <strong>Open the back-office</strong> button appears only if you are granted access, account by account or because you belong to a team responsible for the product. Otherwise the space says so; ask the general administrator. Having a product in your scope is not enough to open its back-office.</p><h2 id="opening-a-product-back-office" tabindex="-1">Opening a product back-office <a class="header-anchor" href="#opening-a-product-back-office" aria-label="Permalink to &quot;Opening a product back-office&quot;">​</a></h2><ol><li>Open the product&#39;s space, then <strong>Open the back-office</strong>.</li><li>The back-office signs you in with your M&#39;City account (a &quot;Sign in with M&#39;City&quot; button on its sign-in page, if you go there directly).</li><li>If you are not signed in to M&#39;City yet, the M&#39;City sign-in (and its two-factor authentication) comes first.</li></ol><p>Signing out of M&#39;City also closes the back-office sessions opened from that session. What you can do in a back-office depends on your position: for Auticway, see <a href="./auticway.html">Auticway back-office</a>.</p>',20)])])}const g=o(n,[["render",i]]);export{h as __pageData,g as default};
